import mime from "mime-types";
import ts from "typescript";
import fs from "fs";
const src = fs.readFileSync("src/utils/mimeType.ts", "utf8");
const js = ts.transpileModule(src, { compilerOptions: { module: ts.ModuleKind.ESNext } }).outputText;
const { getMimeTypeForPath } = await import("data:text/javascript," + encodeURIComponent(js));
const DEFAULT = "application/octet-stream";
const oldImpl = (p) => mime.lookup(p) || DEFAULT;

let diffType = 0, flipSkip = 0;
const allExt = Object.keys(mime.types);
for (const ext of allExt) {
  const p = `note/a.${ext}`;
  const o = oldImpl(p), n = getMimeTypeForPath(p);
  const so = o.startsWith("text/"), sn = n.startsWith("text/");
  if (so !== sn) { console.log(`SKIP-FLIP .${ext}: old=${o} new=${n}`); flipSkip++; }
  else if (o !== n) diffType++;
}
console.log(`\nextensions checked: ${allExt.length}`);
console.log(`skip-decision flips: ${flipSkip}   <-- must be 0`);
console.log(`stored-type diffs (non-text, both uploaded): ${diffType}`);

const OBS = ["md","canvas","png","webp","jpg","jpeg","gif","bmp","svg","avif","mp3",
  "webm","wav","m4a","ogg","3gp","flac","mp4","ogv","mov","mkv","pdf"];
console.log("\n=== Obsidian attachment types ===");
let bad = 0;
for (const ext of OBS) {
  const p = `a.${ext}`, o = oldImpl(p), n = getMimeTypeForPath(p);
  if (o !== n) { console.log(`  DIFF .${ext}: old=${o} new=${n}`); bad++; }
}
console.log(bad === 0 ? "  all identical to mime-types" : `  ${bad} differ`);

console.log("\n=== edge cases ===");
