// Throwaway: dump gray-matter's parse of every vault note, plus our regex split.
const fs = require("fs"), path = require("path");
const matter = require("gray-matter");
const VAULT = "/Users/trang.doan/Documents/testVault";
const OUT = process.argv[2];

const FRONTMATTER_BLOCK = /^---[ \t]*\r?\n([\s\S]*?)\r?\n?^---[ \t]*(?:\r?\n|$)/m;
const splitFrontmatter = (content) => {
  const m = FRONTMATTER_BLOCK.exec(content);
  if (!m || m.index !== 0) return { yaml: null, body: content };
  return { yaml: m[1] ?? "", body: content.slice(m[0].length) };
};

const walk = (dir, acc = []) => {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.name === ".obsidian" || e.name === ".git") continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, acc);
    else if (e.name.endsWith(".md")) acc.push(p);
  }
  return acc;
};

const files = walk(VAULT);
const out = [];
let gmThrew = 0, hasFm = 0;
for (const f of files) {
  const content = fs.readFileSync(f, "utf8");
  const rel = path.relative(VAULT, f);
  let gm = null, err = null;
  try {
    const r = matter(content);
    gm = { data: r.data ?? {}, body: r.content ?? "" };
  } catch (e) { err = String(e.message).slice(0, 120); gmThrew++; }
  const split = splitFrontmatter(content);
  if (split.yaml !== null) hasFm++;
  out.push({ rel, gmData: gm && gm.data, gmBody: gm && gm.body, gmErr: err,
             yaml: split.yaml, body: split.body });
}
fs.writeFileSync(OUT, JSON.stringify(out));
console.log(`files: ${files.length}  with frontmatter: ${hasFm}  gray-matter threw: ${gmThrew}`);

// Body equivalence is checkable right here: gray-matter vs our split, no YAML involved.
let bodyDiff = 0, fmPresenceDiff = 0;
for (const r of out) {
  if (r.gmErr) continue;
  const gmHasFm = Object.keys(r.gmData).length > 0;
  const ourHasFm = r.yaml !== null && r.yaml.trim() !== "";
  if (gmHasFm !== ourHasFm) { fmPresenceDiff++; if (fmPresenceDiff <= 5) console.log(`  FM-PRESENCE ${r.rel}: gray-matter=${gmHasFm} ours=${ourHasFm}`); }
  if (r.gmBody !== r.body) { bodyDiff++; if (bodyDiff <= 5) console.log(`  BODY-DIFF ${r.rel}`); }
}
console.log(`frontmatter-presence disagreements: ${fmPresenceDiff}`);
console.log(`body disagreements: ${bodyDiff}  (note: body is never consumed by callers)`);
EOF
