const gm = JSON.parse(fs.readFileSync("gm.json", "utf8"));
const obs = JSON.parse(fs.readFileSync("obs.json", "utf8"));
const obsBy = new Map(obs.rows.map((r) => [r.rel, r]));

let compared = 0, identical = 0;
const diffs = [];
for (const g of gm) {
  const o = obsBy.get(g.rel);
  if (!o) continue;
  const gData = g.gmData ?? {};
  const oData = o.data ?? {};
  compared++;
  const keys = new Set([...Object.keys(gData), ...Object.keys(oData)]);
  const fieldDiffs = [];
  for (const k of keys) {
    const a = JSON.stringify(gData[k]), b = JSON.stringify(oData[k]);
    if (a !== b) fieldDiffs.push({ k, gray: a, obs: b });
  }
  if (fieldDiffs.length === 0) identical++;
  else diffs.push({ rel: g.rel, fieldDiffs });
}
console.log(`compared: ${compared}   identical: ${identical}   differing: ${diffs.length}`);

// The only two fields any caller reads.
const READ = ["nodeTypeId", "importedFromRid"];
let readFieldDiffs = 0;
for (const d of diffs)
  for (const f of d.fieldDiffs)
    if (READ.includes(f.k)) { readFieldDiffs++; console.log(`  READ-FIELD DIFF ${d.rel} ${f.k}: gray=${f.gray} obs=${f.obs}`); }
console.log(`\ndiffs in fields callers actually read (${READ.join(", ")}): ${readFieldDiffs}  <-- must be 0`);

const byKind = {};
for (const d of diffs)
  for (const f of d.fieldDiffs) {
    const kind = f.obs === undefined ? "missing-in-obsidian"
      : f.gray === undefined ? "missing-in-gray-matter"
      : /^"\d{4}-\d\d-\d\dT/.test(f.gray) && /^"\d{4}-\d\d-\d\d/.test(f.obs) ? "date-coercion"
      : "value";
    (byKind[kind] ??= []).push(`${d.rel} :: ${f.k}  gray=${f.gray} obs=${f.obs}`);
  }
console.log("\n=== differences by kind ===");
for (const [k, v] of Object.entries(byKind)) {
  console.log(`\n${k}: ${v.length}`);
  v.slice(0, 6).forEach((x) => console.log("   " + x.slice(0, 150)));
}
EOF
