// Throwaway: prove the lookbehind removal matches identically.
const fs = require("fs"), path = require("path");
const OLD = /(?<!!)\[([^\]]*)\]\(([^)]+)\)/g;
const NEW = /(!?)\[([^\]]*)\]\(([^)]+)\)/g;
// Sentinel transform: both must produce the same output on the same input.
const applyOld = (s) => s.replace(new RegExp(OLD.source, "g"), (m, text, p) => {
  if (!p) return m;
  return `<L text=${JSON.stringify(text)} path=${JSON.stringify(p)}>`;
});
const applyNew = (s) => s.replace(new RegExp(NEW.source, "g"), (m, pre, text, p) => {
  if (pre) return m;
  if (!p) return m;
  return `<L text=${JSON.stringify(text)} path=${JSON.stringify(p)}>`;
});

const walk = (d, acc = []) => {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (e.name === ".obsidian" || e.name === ".git") continue;
    const p = path.join(d, e.name);
    e.isDirectory() ? walk(p, acc) : e.name.endsWith(".md") && acc.push(p);
  }
  return acc;
};

const SYNTHETIC = [
  "![alt](img.png)", "[text](page.md)", "![](a.png) and [b](c.md)",
  "!![weird](x.md)", "[a](b) ![c](d)", "text ! [spaced](x.md)",
  "[](empty.md)", "[nested [br]](p.md)", "![img](a b.png)",
  "line1\n![x](y.png)\nline2 [z](w.md)", "!\n[after-newline-bang](p.md)",
  "[link](http://ex.com/a(b)", "\\![escaped](x.md)", "![[wikilink embed]]",
];

let files = walk("/Users/trang.doan/Documents/testVault");
let diff = 0, checked = 0, withLinks = 0;
for (const f of files) {
  const s = fs.readFileSync(f, "utf8");
  checked++;
  const a = applyOld(s), b = applyNew(s);
  if (a.includes("<L ")) withLinks++;
  if (a !== b) { diff++; if (diff <= 5) console.log("VAULT DIFF:", path.basename(f)); }
}
console.log(`vault notes checked: ${checked}  containing markdown links: ${withLinks}  differing: ${diff}`);

let sDiff = 0;
for (const s of SYNTHETIC) {
  const a = applyOld(s), b = applyNew(s);
  if (a !== b) { sDiff++; console.log(`SYNTH DIFF ${JSON.stringify(s)}\n  old=${a}\n  new=${b}`); }
}
console.log(`synthetic cases: ${SYNTHETIC.length}  differing: ${sDiff}`);
EOF
