// Throwaway: reload the plugin from the rebuilt bundle and prove the changed paths still work.
const list = await (await fetch("http://127.0.0.1:9222/json/list")).json();
const t = list.find((x) => x.type === "page" && x.url.includes("obsidian.md"));
const ws = new WebSocket(t.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const send = (m, p = {}) =>
  new Promise((res, rej) => {
    const i = ++id;
    pending.set(i, { res, rej });
    ws.send(JSON.stringify({ id: i, method: m, params: p }));
  });
const errors = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.method === "Runtime.exceptionThrown")
    errors.push(
      (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text || "")
        .slice(0, 200),
    );
  if (m.method === "Runtime.consoleAPICalled" && m.params.type === "error")
    errors.push("console.error: " + m.params.args.map((a) => a.value ?? a.description).join(" ").slice(0, 200));
  if (m.id && pending.has(m.id)) {
    const p = pending.get(m.id);
    pending.delete(m.id);
    m.error ? p.rej(new Error(JSON.stringify(m.error))) : p.res(m.result);
  }
};
await new Promise((r) => (ws.onopen = r));
await send("Runtime.enable");
const ev = async (expression) => {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 500));
  return r.result.value;
};

const ID = "@discourse-graph/obsidian";
console.log("build in vault:", await ev(`(function(){
  var fs = require("fs");
  var p = app.vault.adapter.basePath + "/.obsidian/plugins/" +
          app.plugins.manifests[${JSON.stringify(ID)}].dir.split("/").pop() + "/main.js";
  var s = fs.readFileSync(p, "utf8");
  return JSON.stringify({
    hasSplitFrontmatter: s.indexOf("FRONTMATTER_BLOCK") > -1 || s.indexOf("splitFrontmatter") > -1,
    hasGetMimeTypeForPath: s.indexOf("getMimeTypeForPath") > -1,
    grayMatterGone: s.indexOf("gray-matter") === -1,
    requireFsGone: s.indexOf('require("fs")') === -1,
    requirePathGone: s.indexOf('require("path")') === -1,
    lookbehindGone: s.indexOf("(?<!") === -1
  });
})()`));

await ev(`app.plugins.disablePlugin(${JSON.stringify(ID)})`);
await ev(`app.plugins.enablePlugin(${JSON.stringify(ID)})`);
console.log("plugin loaded:", await ev(`(function(){
  var p = app.plugins.plugins[${JSON.stringify(ID)}];
  return JSON.stringify({
    loaded: !!p,
    commands: Object.keys(app.commands.commands).filter(function(c){ return c.indexOf("discourse-graph") === 0 || c.indexOf("@discourse-graph") === 0; }).length,
    settingsOk: !!(p && p.settings)
  });
})()`));

console.log("runtime errors during reload:", errors.length);
errors.slice(0, 6).forEach((e) => console.log("  " + e));
ws.close();

